// Generated exact distances; see provenance/KNKA-GUIDE.md. No position-only search scores.
import {Board,moveToUci} from './board.js';
function index(board,side=1){
 let rk=-1,bk=-1,kn=-1,ad=-1;
 const squares=board.squares;if(squares.length!==90||(board.turn!==1&&board.turn!==-1))return -1;
 for(let s=0;s<90;s++){const p=squares[side===1?s:89-s]*side;if(p===0)continue;if(p===7&&rk<0)rk=s;else if(p===-7&&bk<0)bk=s;else if(p===4&&kn<0)kn=s;else if(p===-2&&ad<0)ad=s;else return -1;}
 const rr=Math.floor(rk/9),rc=rk%9,br=Math.floor(bk/9),bc=bk%9;
 if(rk<0||bk<0||kn<0||rr<7||rr>9||rc<3||rc>5||br<0||br>2||bc<3||bc>5)return -1;
 const ai=ad<0?0:[3,5,13,21,23].indexOf(ad)+1;if(ad>=0&&ai===0)return -1;
 return (((((rr-7)*3+rc-3)*9+br*3+bc-3)*90+kn)*6+ai)*2+(board.turn*side===-1?1:0);
}
const data=Uint8Array.from(atob(""),x=>x.charCodeAt(0));

function distance(board,side=1){const i=index(board,side);return i>=0&&data[i]?data[i]-1:null;}
export function probeEndgameGuide(prepared, shouldStop=()=>false){
 const {board,judge,context}=prepared;
 if(shouldStop())return null;
 if(context.ruleProfile!=='pikafish-public-b562'||context.historyComplete!==true||context.adjudication.terminal)return null;
 const side=board.turn,rank=distance(board,side);if(rank===null||rank<=0||!Number.isSafeInteger(board.halfmove)||board.halfmove<0||board.halfmove+rank>=120)return null;
 const states=judge.states;if(!Array.isArray(states)||!states.length||states.at(-1).canonical!==board.toFEN().split(' ').slice(0,2).join(' '))return null;
 for(let i=0;i<states.length-1;i++){if(shouldStop())return null;const prior=new Board(states[i].canonical+' - - 0 1');const d=distance(prior,side);if(d!==null&&d<=rank)return null;}
 let chosen=null;for(const move of board.generateLegalMoves()){const u=board.makeMove(move);let child;try{child=distance(board,side);}finally{board.unmakeMove(u);}if(child===rank-1){const text=moveToUci(move);if(chosen===null||text<chosen)chosen=text;}}
 if(chosen!==null&&!shouldStop())return Object.freeze({move:chosen,remainingPlies:rank,source:'knka-exact-v1',root:board.toFEN().split(' ').slice(0,2).join(' ')});
 return null;
}
